package com.bank.orders;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class BankDemo {
    private static final Logger log = Logger.getLogger(BankDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Equity reliance = new Equity("RELIANCE", new BigDecimal("2450.50"));

        // Rajesh (SAV2001) buys, Priya (CUR3001) sells — both typed to Equity.
        Order<Equity> rajeshBuy  = new BuyOrder<>("SAV2001", reliance, 100);
        Order<Equity> priyaSell  = new SellOrder<>("CUR3001", reliance, 40);

        RiskEngine engine = new RiskEngine();

        // Wildcard list: any order of any instrument.
        List<Order<? extends Instrument>> orders = List.of(rajeshBuy, priyaSell);
        for (Order<? extends Instrument> o : orders) {
            log.info(() -> "Notional = Rs." + engine.notional(o) + " | " + engine.action(o));
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
