package com.bank.orders;

import java.math.BigDecimal;

// Generic sealed interface: closed set {BuyOrder, SellOrder}, each carrying T.
public sealed interface Order<T extends Instrument> permits BuyOrder, SellOrder {
    String accountId();
    T instrument();
    int quantity();
    default BigDecimal grossValue() {
        return instrument().price().multiply(BigDecimal.valueOf(quantity()));
    }
}
