package com.bank.orders;

// Permitted subtype keeps the type parameter → stays generic.
public final class BuyOrder<T extends Instrument> implements Order<T> {
    private final String accountId;
    private final T instrument;
    private final int quantity;

    public BuyOrder(String accountId, T instrument, int quantity) {
        this.accountId = accountId;
        this.instrument = instrument;
        this.quantity = quantity;
    }
    @Override public String accountId() { return accountId; }
    @Override public T instrument() { return instrument; }
    @Override public int quantity() { return quantity; }
}
