package com.bank.orders;

import java.math.BigDecimal;

public class RiskEngine {

    // Wildcard parameter: accepts an order of ANY instrument type.
    public BigDecimal notional(Order<? extends Instrument> order) {
        return order.grossValue(); // read via the interface, no exact T needed
    }

    // Exhaustive switch over the CLOSED set — wildcard patterns, no default.
    public String action(Order<? extends Instrument> order) {
        return switch (order) {
            case BuyOrder<?> b  -> "BUY "  + b.quantity() + " " + b.instrument().symbol()
                                   + " for " + b.accountId();
            case SellOrder<?> s -> "SELL " + s.quantity() + " " + s.instrument().symbol()
                                   + " for " + s.accountId();
        };
    }
}
